package com.projects.demo;

import org.springframework.data.jpa.repository.JpaRepository;

import org.springframework.stereotype.Repository;

@Repository
public interface DeliveryRepository1 extends JpaRepository<DeliveryEntity, Integer>{
	 long countByCurrentStatus(String currentStatus);  //It is used to count how many delivery records have a particular status, such as Delivered, In Transit, or Pending.
}

//Here countByCurrentStatus is automatically generated by Jpa Repository because we are extending it